import React, { useState, useEffect, useRef } from "react";
import "./Header.css";
import { Link, useLocation } from "react-router-dom";
import { greeting } from "../../portfolio.js";
import { CgSun } from "react-icons/cg/";
import { HiMoon } from "react-icons/hi";
import LoginButton from "../auth/LoginButton";
import {
  startNavHop,
  takeFlight,
  hopAllowed,
  hopInFlight,
} from "./navHop";

// The nav, in render order. .menu a:nth-child(n) drives the staggered
// entrance, so the order here is load-bearing.
const NAV_ITEMS = [
  { to: "/home", cls: "homei", label: "Home" },
  { to: "/education", cls: "ec", label: "Education" },
  { to: "/experience", cls: "xp", label: "Experience" },
  { to: "/projects", cls: "projects", label: "Projects" },
  { to: "/learn", cls: "learn", label: "Learn" },
  { to: "/contact", cls: "cr", label: "Contact" },
  { to: "/myspace", cls: "myspace", label: "Agents" },
  { to: "/blog", cls: "blog", label: "Blogs" },
];

// Degrees of tilt at the very corner of a key.
const MAX_TILT = 9;

// ---- route hop ------------------------------------------------------------
// Which key a path belongs to, for the hop only. Looser than isActive(): a
// child route (/projects/some-slug, /blog/a-post) still counts as its parent
// key, so leaving a project detail page hops off Projects rather than off
// nowhere.
const findNavIndex = (pathname) => {
  const path = "/" + (pathname || "").replace(/^\/+/, "").toLowerCase();
  const exact = NAV_ITEMS.findIndex(
    (item) => item.to === path || (path === "/" && item.to === "/home")
  );
  if (exact !== -1) return exact;
  return NAV_ITEMS.findIndex((item) => path.startsWith(`${item.to}/`));
};

// Every page renders its own <Header> (see src/pages/*), so navigating tears
// this component down and builds a new one. Anything that has to survive a
// route change therefore cannot live in state or a ref — it has to outlive the
// component. Two things do:
//
//   lastNavIdx  which key we were on before this mount, i.e. where to hop from
//   hasEntered  whether the staggered entrance has already played this session
let lastNavIdx = null;
let hasEntered = false;

const Header = (props) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);
  const [isScrolled, setIsScrolled] = useState(false);
  const [isPulsing, setIsPulsing] = useState(false);
  const [showMenuHint, setShowMenuHint] = useState(false);
  // What an in-flight hop is about to do to this header's keys. `hold` keeps
  // the destination dark until the ball actually touches it; `impact` carries
  // the bounce and the dips. Two pieces of state because they end at different
  // moments — the key ignites on contact, then goes on bouncing.
  const [hold, setHold] = useState(null);
  const [impact, setImpact] = useState(null);
  const location = useLocation();

  // The nav links by index, so a hop can measure where it starts and ends.
  const linkRefs = useRef([]);
  const hopTimers = useRef([]);

  // The two entrances — the bar's own slide-in and the staggered deal of the
  // keys — belong to the first paint of the session, not to every page change.
  // Remounting replayed both on each navigation: the bar dropped in from
  // translateY(-80px) over 0.8s while the row blanked and re-dealt all eight
  // keys over 1.3s, which is what a page switch used to look like. Read from a
  // ref so a re-render cannot flip it mid-life; written in an effect so a
  // double render could not consume the first mount's turn.
  const skipEntrance = useRef(hasEntered);
  useEffect(() => {
    hasEntered = true;
  }, []);

  // Function to check if a path is active
  const isActive = (path) => {
    const currentPath = location.pathname.replace(/^\//, "");
    return (
      currentPath === path.replace(/^\//, "") ||
      (currentPath === "" && path === "/home")
    );
  };

  // 👇 NEW: Show menu hint for first-time mobile visitors
  useEffect(() => {
    const hasSeenMenuHint = localStorage.getItem("hasSeenMenuHint");

    if (!hasSeenMenuHint && isMobile) {
      // Small delay so the page loads first
      const showTimer = setTimeout(() => {
        setShowMenuHint(true);
      }, 1500);

      // Auto-hide after 6 seconds
      const hideTimer = setTimeout(() => {
        setShowMenuHint(false);
        localStorage.setItem("hasSeenMenuHint", "true");
      }, 7500);

      return () => {
        clearTimeout(showTimer);
        clearTimeout(hideTimer);
      };
    }
  }, [isMobile]);

  // 👇 NEW: Dismiss hint when menu is opened
  const dismissHint = () => {
    setShowMenuHint(false);
    localStorage.setItem("hasSeenMenuHint", "true");
  };

  // Arriving. Whichever header is on screen when the ball lands owns what
  // happens to the keys, and that is always this one — the header that
  // launched the hop was unmounted by the navigation that caused it.
  //
  // A hop normally starts on the click (handleNavClick, below), so it is
  // already moving before React commits anything. Navigations with no click
  // behind them — browser back/forward, a link inside a page — have no such
  // moment, so this is also where those get launched: late, but present.
  useEffect(() => {
    const toIdx = findNavIndex(location.pathname);
    const fromIdx = lastNavIdx;
    lastNavIdx = toIdx;

    let flight = takeFlight(toIdx);

    if (!flight && !hopInFlight() && fromIdx !== null && fromIdx !== toIdx) {
      if (fromIdx !== -1 && toIdx !== -1 && hopAllowed()) {
        startNavHop({
          fromEl: linkRefs.current[fromIdx],
          toEl: linkRefs.current[toIdx],
          toIdx,
          keys: linkRefs.current,
        });
        flight = takeFlight(toIdx);
      }
    }

    if (!flight) return;

    // How much of the flight is left. On a heavy page this header can mount
    // after the ball has already landed, in which case everything below runs
    // with no delay and the key simply lights up on arrival.
    const remaining = Math.max(0, flight.endsAt - performance.now());
    const elapsed = flight.dur - remaining;

    // Only the dips the ball has not already flown past.
    const wake = {};
    Object.keys(flight.wake).forEach((i) => {
      const at = flight.wake[i] - elapsed;
      if (at > 0) wake[i] = Math.round(at);
    });

    setImpact({ toIdx, landDelay: Math.round(remaining), wake });
    // Below ~60ms there is no perceptible wait left to stage, and holding the
    // key dark for a couple of frames would read as a flicker.
    if (remaining > 60) setHold(toIdx);

    hopTimers.current.forEach(clearTimeout);
    hopTimers.current = [
      // Contact: the key takes the accent it has been withholding.
      setTimeout(() => setHold(null), remaining),
      // Then the bounce and the ripple finish, and the keys go back to being
      // plain CSS.
      setTimeout(() => setImpact(null), remaining + 860),
    ];
  }, [location.pathname]);

  useEffect(() => () => hopTimers.current.forEach(clearTimeout), []);

  // Launch on the click itself, before React starts rebuilding the page. That
  // rebuild costs 30ms on a light route and over a second on a heavy one;
  // waiting for it would put the entire hop inside a window where the main
  // thread is blocked and nothing is painted.
  const handleNavClick = (i) => () => {
    setIsMenuOpen(false);

    const fromIdx = lastNavIdx;
    if (fromIdx === null || fromIdx === i || fromIdx === -1) return;
    if (!hopAllowed()) return;

    const fromEl = linkRefs.current[fromIdx];
    const launched = startNavHop({
      fromEl,
      toEl: linkRefs.current[i],
      toIdx: i,
      keys: linkRefs.current,
    });
    if (!launched) return;

    // The key pushes off. Imperative, because this element is about to be
    // unmounted along with the rest of the header — there is no render left
    // to do it in.
    if (fromEl) {
      fromEl.classList.remove("hop-launch");
      void fromEl.offsetWidth;
      fromEl.classList.add("hop-launch");
    }

    // Claim the move now, so the mount that follows knows the hop is already
    // in the air and does not launch a second one.
    lastNavIdx = i;
  };

  // Scroll detection with pulse effect
  useEffect(() => {
    let lastScrollY = window.scrollY;
    let ticking = false;
    let pulseTimeout = null;

    const handleScroll = () => {
      lastScrollY = window.scrollY;

      if (!ticking) {
        window.requestAnimationFrame(() => {
          if (lastScrollY > 50) {
            setIsScrolled(true);
          } else {
            setIsScrolled(false);
          }

          if (Math.abs(lastScrollY % 100) < 5) {
            setIsPulsing(true);
            clearTimeout(pulseTimeout);
            pulseTimeout = setTimeout(() => {
              setIsPulsing(false);
            }, 600);
          }

          ticking = false;
        });

        ticking = true;
      }
    };

    window.addEventListener("scroll", handleScroll, { passive: true });

    return () => {
      window.removeEventListener("scroll", handleScroll);
      clearTimeout(pulseTimeout);
    };
  }, []);

  // Handle resize
  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth <= 768);
      if (window.innerWidth > 768) {
        setIsMenuOpen(false);
        setShowMenuHint(false);
      }
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  // Close menu when route changes
  useEffect(() => {
    setIsMenuOpen(false);
  }, [location]);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
    dismissHint(); // 👈 Dismiss hint when user clicks menu
  };

  const link = "/home";

  // Tilts a key away from the pointer and slides its specular highlight, so
  // the corner under the cursor reads as the corner being pressed.
  //
  // offsetX/offsetY are measured in the element's own *untransformed* box, so
  // unlike getBoundingClientRect() they cannot pick up the rotation this
  // handler just applied — no feedback loop, no drift when the cursor stops.
  const handleKeyTilt = (e) => {
    const el = e.currentTarget;
    const w = el.offsetWidth || 1;
    const h = el.offsetHeight || 1;
    const px = e.nativeEvent.offsetX / w;
    const py = e.nativeEvent.offsetY / h;
    el.style.setProperty("--ry", `${(px - 0.5) * 2 * MAX_TILT}deg`);
    el.style.setProperty("--rx", `${(0.5 - py) * 2 * MAX_TILT}deg`);
    el.style.setProperty("--mx", `${px * 100}%`);
    el.style.setProperty("--my", `${py * 100}%`);
  };

  const resetKeyTilt = (e) => {
    const el = e.currentTarget;
    el.style.setProperty("--rx", "0deg");
    el.style.setProperty("--ry", "0deg");
    el.style.setProperty("--mx", "50%");
    el.style.setProperty("--my", "50%");
  };

  function changeTheme() {
    if (props.theme.name === "light") {
      props.setTheme("dark");
      localStorage.setItem("theme", "dark");
    } else {
      props.setTheme("light");
      localStorage.setItem("theme", "light");
    }
  }

  const icon =
    props.theme.name === "dark" ? (
      <HiMoon
        strokeWidth={1}
        size={20}
        color={props.theme.name === "light" ? "#F9D784" : "#A7A7A7"}
      />
    ) : (
      <CgSun
        strokeWidth={1}
        size={20}
        color={props.theme.name === "light" ? "#F9D784" : "#A7A7A7"}
      />
    );

  return (
    <div className="header-container">
      {isMenuOpen && (
        <div
          className={`menu-overlay ${isMenuOpen ? "active" : ""}`}
          onClick={() => setIsMenuOpen(false)}
        />
      )}
      {/* The header had no theme hook at all — its colours came entirely from
          the inline style on each link, which is why the [data-theme] rules
          already in Header.css never matched anything. */}
      <header
        className={`header ${isScrolled ? "scrolled" : ""} ${
          isPulsing ? "pulse" : ""
        } ${skipEntrance.current ? "settled" : ""}`}
        data-theme={props.theme?.name}
      >
        <Link to={link} className="logo">
          <span className="logo-name" style={{ color: props.theme.text }}>
            {greeting.logo_name}
          </span>
        </Link>

        {isMobile && (
          <div className="menu-icon-wrapper">
            {/* 👇 NEW: Menu discovery hint */}
            {showMenuHint && (
              <div className="menu-hint" onClick={dismissHint}>
                <div className="menu-hint-content">
                  <span className="menu-hint-arrow">✨</span>
                  <span className="menu-hint-text">Tap here for menu!</span>
                </div>
                <div className="menu-hint-ring"></div>
              </div>
            )}

            <button
              className={`menu-icon ${isMenuOpen ? "open" : ""} ${
                showMenuHint ? "hint-active" : ""
              }`}
              onClick={toggleMenu}
              aria-label="Toggle Menu"
              style={{
                color: props.theme.text,
                background: "transparent",
                border: "none",
                padding: 0,
                cursor: "pointer",
              }}
            >
              <span style={{ backgroundColor: props.theme.text }}></span>
              <span style={{ backgroundColor: props.theme.text }}></span>
              <span style={{ backgroundColor: props.theme.text }}></span>
            </button>
          </div>
        )}

        <nav
          className={`menu ${isMenuOpen ? "open" : ""} ${
            skipEntrance.current ? "settled" : ""
          }`}
        >
          {NAV_ITEMS.map((item, i) => {
            const landing = impact && impact.toIdx === i;
            // The destination is the current page from the moment the route
            // changes, but it does not *look* it until the ball gets there.
            // Withholding `active` is what makes the light arrive with the
            // hop rather than with the click.
            const lit = isActive(item.to) && hold !== i;
            const dip = impact && impact.wake[i] != null;
            // Keys either side of the landing take the shock a beat after it,
            // outwards, so the row absorbs the impact instead of one key
            // swallowing it whole.
            const ripple =
              impact && !landing && !dip ? Math.abs(i - impact.toIdx) : 0;

            return (
              <Link
                key={item.to}
                to={item.to}
                ref={(el) => {
                  linkRefs.current[i] = el;
                }}
                className={[
                  item.cls,
                  lit ? "active" : "",
                  landing ? "hop-land" : "",
                  dip ? "hop-wake" : "",
                  ripple && ripple <= 3 ? "hop-ripple" : "",
                ]
                  .filter(Boolean)
                  .join(" ")}
                style={{
                  color: props.theme.text,
                  ...(landing
                    ? { "--land-delay": `${impact.landDelay}ms` }
                    : null),
                  ...(dip ? { "--wake-delay": `${impact.wake[i]}ms` } : null),
                  ...(ripple
                    ? {
                        "--wake-delay": `${
                          impact.landDelay + 40 + ripple * 45
                        }ms`,
                      }
                    : null),
                }}
                onClick={handleNavClick(i)}
                onPointerMove={handleKeyTilt}
                onPointerLeave={resetKeyTilt}
              >
                {item.label}
              </Link>
            );
          })}

          {/* The ball itself is not here: it is a plain DOM layer on
              document.body, built on the click by navHop.js, because this
              header is torn down by the very navigation it is animating. */}

          <div className="header-actions">
            <button
              className="theme-toggle-btn"
              onClick={changeTheme}
              aria-label="Toggle Theme"
            >
              {icon}
            </button>

            <LoginButton theme={props.theme} />
          </div>
        </nav>
      </header>
    </div>
  );
};

export default Header;
